283	func runStreaming(_ executable: String, _ arguments: [String], directory: URL, stderrLog: URL, onLine: (String) -> Void) -> Int32 {
284	    lastRunFailure = nil
285	    FileManager.default.createFile(atPath: stderrLog.path, contents: nil)
286	    let errorLog = FileHandle(forWritingAtPath: stderrLog.path)
287	    defer { try? errorLog?.close() }
288	    let pipe = Pipe()
289	
290	    func prepared(_ url: String, _ args: [String]) -> Process {
291	        let process = Process()
292	        process.executableURL = URL(fileURLWithPath: url)
293	        process.arguments = args
294	        process.environment = childEnvironment()
295	        process.currentDirectoryURL = directory
296	        // codex exec 는 stdin 이 터미널이 아니면 EOF 까지 추가 입력을 기다린다.
297	        process.standardInput = FileHandle.nullDevice
298	        process.standardError = errorLog ?? FileHandle.nullDevice
299	        process.standardOutput = pipe
300	        return process
301	    }
302	
303	    var process = prepared(executable, arguments)
304	    do {
305	        try process.run()
306	    } catch {
307	        // 셔뱅 없는 스크립트나 셸 래퍼는 커널이 못 열어도 셸은 연다 (Exec format error).
308	        // 로그인 셸에 한 번 더 맡겨 본다.
309	        let shell = ProcessInfo.processInfo.environment["SHELL"] ?? "/bin/zsh"
310	        process = prepared(shell, ["-lc", "exec \"$0\" \"$@\"", executable] + arguments)
311	        do {
312	            try process.run()
313	        } catch {
314	            let reason = "\(executable) 을 실행하지 못했어요 — \(error.localizedDescription)"
315	            lastRunFailure = reason
316	            say(Style.red("실행 실패: \(reason)"))
317	            return -1
318	        }
319	    }
320	
321	    let handle = pipe.fileHandleForReading
322	    var buffer = Data()
323	    while true {
324	        let chunk = handle.availableData
325	        if chunk.isEmpty { break }
326	        buffer.append(chunk)
327	        while let newline = buffer.firstIndex(of: 0x0A) {
328	            onLine(String(decoding: buffer[buffer.startIndex..<newline], as: UTF8.self))
329	            buffer.removeSubrange(buffer.startIndex...newline)
330	        }
331	    }
332	    if !buffer.isEmpty {
333	        onLine(String(decoding: buffer, as: UTF8.self))
334	    }
335	    process.waitUntilExit()
336	    if process.terminationReason == .uncaughtSignal {
337	        lastRunFailure = "중간에 끊겼어요 (신호 \(process.terminationStatus))"
338	    }
339	    return process.terminationStatus
